let iteration = Number(pm.collectionVariables.get("loginRateIteration") || 1);

console.log(`Iteration: ${iteration} | Status: ${pm.response.code}`);

const limit = pm.response.headers.get("RateLimit");
const policy = pm.response.headers.get("RateLimit-Policy");

if (limit) console.log("RateLimit:", limit);
if (policy) console.log("RateLimit-Policy:", policy);

// Check that the response is either 401 or 429
pm.test("Request returns 401 or 429", function () {
    pm.expect([401, 429]).to.include(pm.response.code);
});

if (pm.response.code === 429) {

    pm.test("Authentication rate limit enforced", function () {
        const res = pm.response.json();

        pm.expect(res.success).to.eql(false);
        pm.expect(res.message).to.include(
            "Too many authentication requests"
        );
    });

    console.log(`Rate limit reached after ${iteration} requests`);

    pm.collectionVariables.unset("loginRateIteration");
    pm.execution.setNextRequest(null);

} else if (pm.response.code === 401 && iteration < 15) {

    pm.collectionVariables.set("loginRateIteration", iteration + 1);
    pm.execution.setNextRequest(pm.info.requestId);

} else {

    pm.test("Rate limiter reached before safety limit", function () {
        pm.expect(pm.response.code).to.equal(429);
    });

    pm.collectionVariables.unset("loginRateIteration");
    pm.execution.setNextRequest(null);
}

